const DAILY_CONNECTIONS=Array.from({length:120},(_,day)=>{let selected=[],used=new Set();let seed=(day+1)*2654435761>>>0;const rand=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return (seed>>>0)/4294967296};let order=EXTRA_GROUPS.map((_,i)=>i);for(let i=order.length-1;i>0;i--){let j=Math.floor(rand()*(i+1));[order[i],order[j]]=[order[j],order[i]];}for(let t=0;t<order.length&&selected.length<4;t++){let g=EXTRA_GROUPS[order[t]];if(g.slice(1).some(w=>used.has(w)))continue;selected.push(g);g.slice(1).forEach(w=>used.add(w));}return {groups:selected.map(g=>g.slice(1)),labels:selected.map(g=>g[0])};});
const DAILY_NUMBERS=Array.from({length:90},(_,day)=>Array.from({length:12},(_,j)=>{const n=day*12+j;const start=2+(n%41),step=2+(Math.floor(n/41)%17),kind=n%6;let seq,answer,h;if(kind===0){seq=Array.from({length:5},(_,i)=>start+i*step);answer=start+5*step;h=`Добавяме ${step}.`;}else if(kind===1){seq=Array.from({length:5},(_,i)=>start+i*i*step);answer=start+25*step;h=`Добавяме последователни нечетни кратни на ${step}.`;}else if(kind===2){seq=Array.from({length:5},(_,i)=>start+step*i*(i+1)/2);answer=start+step*15;h=`Разликите нарастват с ${step}.`;}else if(kind===3){seq=Array.from({length:5},(_,i)=>(start%9+2)*Math.pow(2,i));answer=(start%9+2)*32;h='Умножаваме по 2.';}else if(kind===4){seq=Array.from({length:5},(_,i)=>start+step*i*i*i);answer=start+125*step;h=`Кубове, умножени по ${step}, плюс ${start}.`;}else{seq=Array.from({length:5},(_,i)=>start+step*i*(i+1));answer=start+30*step;h=`Разликите са ${2*step}, ${4*step}, ${6*step} ...`;}return {s:seq.join(', ')+', ?',a:answer,h};}));

